import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Box, 
  Button, 
  TextField, 
  MenuItem, 
  Typography, 
  Paper, 
  Grid,
  FormControl,
  InputLabel,
  Select,
  CircularProgress,
  Alert,
  useTheme,
  Container,
  Divider,
  InputAdornment,
  FormHelperText,
  ListSubheader
} from '@mui/material';
import { 
  CalendarMonth as CalendarIcon,
  Person as PersonIcon,
  Email as EmailIcon,
  Phone as PhoneIcon,
  Description as NotesIcon,
  Work as WorkIcon,
  Check as CheckIcon,
  CheckCircle as CheckCircleIcon,
  AccessTime as AccessTimeIcon,
  ErrorOutline as ErrorOutlineIcon
} from '@mui/icons-material';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { format, addDays } from 'date-fns';
import { appointmentsService } from '../../services/firebaseService';
import { useAuth } from '../../context/FirebaseAuthContext';

// Service options with icons
const SERVICE_OPTIONS = [
  { value: 'tax_preparation', label: 'Tax Preparation', icon: <WorkIcon /> },
  { value: 'tax_consultation', label: 'Tax Consultation', icon: <WorkIcon /> },
  { value: 'business_tax', label: 'Business Tax Filing', icon: <WorkIcon /> },
  { value: 'personal_tax', label: 'Personal Tax Filing', icon: <PersonIcon /> },
  { value: 'tax_planning', label: 'Tax Planning', icon: <WorkIcon /> },
  { value: 'irs_problem', label: 'IRS Problem Resolution', icon: <WorkIcon /> },
  { value: 'other', label: 'Other Service', icon: <WorkIcon /> },
];

// Generate time slots from 8 AM to 8 PM with 30-minute intervals, grouped by AM/PM
const generateTimeSlots = () => {
  const slots = [];
  const startHour = 8; // 8 AM
  const endHour = 20;  // 8 PM

  for (let hour = startHour; hour <= endHour; hour++) {
    for (let minute of ['00', '30']) {
      // Skip the last 30-minute slot if it's 8:30 PM
      if (hour === endHour && minute === '30') continue;

      const period = hour >= 12 ? 'PM' : 'AM';
      const displayHour = hour > 12 ? hour - 12 : hour;
      const displayHour12 = displayHour === 0 ? 12 : displayHour; // Handle 12 AM/PM

      const time24 = `${hour.toString().padStart(2, '0')}:${minute}`;
      const time12 = `${displayHour12}:${minute} ${period}`;

      slots.push({
        value: time24,
        label: time12,
        period: period,
        hour: hour,
        minute: minute,
        disabled: false
      });
    }
  }

  return slots;
};

const TIME_SLOTS = generateTimeSlots();

// Group time slots by AM/PM
const groupTimeSlots = (slots) => {
  return slots.reduce((groups, slot) => {
    const period = slot.period;
    if (!groups[period]) {
      groups[period] = [];
    }
    groups[period].push(slot);
    return groups;
  }, {});
};

const TIME_SLOTS_GROUPED = groupTimeSlots(TIME_SLOTS);

/* ================== COMPONENT ================== */

const BookAppointmentForm = ({ onClose, onSuccess }) => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const theme = useTheme();

  // Form state
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedDate, setSelectedDate] = useState(addDays(new Date(), 1));
  const [touched, setTouched] = useState({});

  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    service: '',
    date: addDays(new Date(), 1),
    time: '',
    notes: ''
  });

  // Pre-fill user data if available
  useEffect(() => {
    if (currentUser) {
      setFormData(prev => ({
        ...prev,
        firstName: currentUser.displayName?.split(' ')[0] || '',
        lastName: currentUser.displayName?.split(' ').slice(1).join(' ') || '',
        email: currentUser.email || '',
        phone: currentUser.phoneNumber || ''
      }));
    }
  }, [currentUser]);

  // Handle input changes and mark field as touched
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Mark field as touched
    setTouched(prev => ({
      ...prev,
      [name]: true
    }));

    // Clear any previous errors when user starts typing
    if (error) setError('');
  };

  // Handle date changes
  const handleDateChange = (date) => {
    setSelectedDate(date);
    setFormData(prev => ({
      ...prev,
      date: date,
      time: '' // Reset time when date changes
    }));

    // Mark date as touched
    setTouched(prev => ({
      ...prev,
      date: true
    }));
  };

  // Handle time selection
  const handleTimeChange = (e) => {
    setFormData(prev => ({
      ...prev,
      time: e.target.value
    }));

    // Mark time as touched
    setTouched(prev => ({
      ...prev,
      time: true
    }));
  };

  // Field validation functions
  const validateField = (name, value) => {
    switch (name) {
      case 'email':
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(value) ? '' : 'Please enter a valid email address';

      case 'phone':
        const phoneRegex = /^(\+\d{1,3}[- ]?)?\d{10}$/;
        return phoneRegex.test(value.replace(/[\s-]/g, '')) 
          ? '' 
          : 'Please enter a valid 10-digit phone number';

      case 'date':
        const selectedDate = new Date(value);
        return selectedDate >= new Date().setHours(0, 0, 0, 0)
          ? ''
          : 'Please select a future date';

      default:
        return value ? '' : 'This field is required';
    }
  };

  // Form validation
  const validateForm = () => {
    const fieldsToValidate = [
      { name: 'firstName', label: 'First Name' },
      { name: 'lastName', label: 'Last Name' },
      { name: 'email', label: 'Email' },
      { name: 'phone', label: 'Phone' },
      { name: 'service', label: 'Service Type' },
      { name: 'date', label: 'Appointment Date' },
      { name: 'time', label: 'Preferred Time' }
    ];

    // Mark all fields as touched to show validation errors
    const newTouched = {};
    fieldsToValidate.forEach(field => {
      newTouched[field.name] = true;
    });
    setTouched(newTouched);

    // Check for empty required fields
    const emptyFields = fieldsToValidate
      .filter(field => !formData[field.name])
      .map(field => field.label);

    if (emptyFields.length > 0) {
      setError(`Please fill in all required fields: ${emptyFields.join(', ')}`);
      return false;
    }

    // Validate field formats
    for (const field of fieldsToValidate) {
      const error = validateField(field.name, formData[field.name]);
      if (error) {
        setError(`${field.label}: ${error}`);
        return false;
      }
    }

    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!validateForm()) return;

    try {
      setLoading(true);

      // Get the selected time slot
      const selectedTime = TIME_SLOTS.find(t => t.value === formData.time);
      if (!selectedTime) {
        throw new Error('Invalid time selected');
      }

      // Parse the 24-hour time
      const [hours, minutes] = selectedTime.value.split(':').map(Number);

      // Create appointment date with the selected time
      const appointmentDate = new Date(formData.date);
      appointmentDate.setHours(hours, minutes, 0, 0);

      const payload = {
        ...formData,
        userId: currentUser?.uid || 'guest',
        status: 'pending',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        appointmentDate: appointmentDate.toISOString(),
        time24: selectedTime.value, // Already in 24-hour format (e.g., '08:00')
        displayDate: format(appointmentDate, 'MMMM d, yyyy'),
        displayTime: selectedTime.label, // This is the formatted 12-hour time with AM/PM
        serviceLabel: SERVICE_OPTIONS.find(s => s.value === formData.service)?.label || formData.service,
        // Add user info for non-logged in users
        userInfo: currentUser ? null : {
          name: `${formData.firstName} ${formData.lastName}`.trim(),
          email: formData.email,
          phone: formData.phone
        }
      };

      await appointmentsService.createAppointment(payload);
      setSuccess('Appointment booked successfully! We will contact you shortly to confirm.');

      // Reset form but keep user info if logged in
      setFormData(prev => ({
        ...(currentUser ? {
          firstName: prev.firstName,
          lastName: prev.lastName,
          email: prev.email,
          phone: prev.phone
        } : {}),
        service: '',
        date: addDays(new Date(), 1),
        time: '',
        notes: ''
      }));
      setSelectedDate(addDays(new Date(), 1));

      // Close modal after delay if onSuccess is provided
      if (onSuccess) {
        setTimeout(() => {
          onSuccess();
        }, 3000);
      }
    } catch (err) {
      console.error('Error booking appointment:', err);
      setError(err.message || 'Failed to book appointment. Please try again or contact support.');
    } finally {
      setLoading(false);
    }
  };

  // Format date for display
  const formatDisplayDate = (date) => {
    return date ? format(date, 'EEEE, MMMM d, yyyy') : '';
  };

  // Check if a date is disabled (weekends)
  const isWeekend = (date) => {
    const day = date.getDay();
    return day === 0 || day === 6; // Sunday or Saturday
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        <Typography variant="h4" component="h1" gutterBottom align="center">
          Book an Appointment
        </Typography>

        <Divider sx={{ my: 3 }} />

        {error && (
          <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError('')}>
            {error}
          </Alert>
        )}

        {success ? (
          <Box textAlign="center" py={4}>
            <CheckCircleIcon color="success" sx={{ fontSize: 60, mb: 2 }} />
            <Typography variant="h5" gutterBottom>
              {success}
            </Typography>
            <Typography color="text.secondary" paragraph>
              We've sent a confirmation to your email.
            </Typography>
            <Button
              variant="contained"
              color="primary"
              onClick={onClose}
              sx={{ mt: 2 }}
            >
              Close
            </Button>
          </Box>
        ) : (
          <form onSubmit={handleSubmit}>
            <Grid container spacing={3}>
              {/* First Name */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  label="First Name"
                  name="firstName"
                  value={formData.firstName}
                  onChange={handleChange}
                  InputProps={{
                    startAdornment: <PersonIcon sx={{ color: 'action.active', mr: 1 }} />
                  }}
                />
              </Grid>

              {/* Last Name */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  label="Last Name"
                  name="lastName"
                  value={formData.lastName}
                  onChange={handleChange}
                  InputProps={{
                    startAdornment: <PersonIcon sx={{ color: 'action.active', mr: 1, opacity: 0 }} />
                  }}
                />
              </Grid>

              {/* Email */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  type="email"
                  label="Email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  InputProps={{
                    startAdornment: <EmailIcon sx={{ color: 'action.active', mr: 1 }} />
                  }}
                />
              </Grid>

              {/* Phone */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  type="tel"
                  label="Phone Number"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="(123) 456-7890"
                  InputProps={{
                    startAdornment: <PhoneIcon sx={{ color: 'action.active', mr: 1 }} />
                  }}
                />
              </Grid>

              {/* Service Type */}
              <Grid item xs={12}>
                <FormControl fullWidth required>
                  <InputLabel>Service Type</InputLabel>
                  <Select
                    name="service"
                    value={formData.service}
                    onChange={handleChange}
                    label="Service Type"
                    startAdornment={
                      <WorkIcon sx={{ color: 'action.active', mr: 1, ml: 1 }} />
                    }
                  >
                    {SERVICE_OPTIONS.map((option) => (
                      <MenuItem key={option.value} value={option.value}>
                        <Box display="flex" alignItems="center">
                          {option.icon}
                          <Box ml={1}>{option.label}</Box>
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              {/* Date Picker */}
              <Grid item xs={12} sm={6}>
                <LocalizationProvider dateAdapter={AdapterDateFns}>
                  <DatePicker
                    label="Appointment Date"
                    value={selectedDate}
                    onChange={handleDateChange}
                    minDate={new Date()}
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        fullWidth
                        required
                        InputProps={{
                          ...params.InputProps,
                          startAdornment: <CalendarIcon sx={{ color: 'action.active', mr: 1 }} />
                        }}
                      />
                    )}
                  />
                </LocalizationProvider>
              </Grid>

              {/* Time Slot - Enhanced with Material-UI */}
              <Grid item xs={12} sm={6}>
                <FormControl 
                  fullWidth
                  required
                  error={touched.time && !formData.time}
                  variant="outlined"
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                      backgroundColor: 'background.paper',
                      '&:hover': {
                        '& .MuiOutlinedInput-notchedOutline': {
                          borderColor: 'primary.light',
                        },
                      },
                      '&.Mui-focused': {
                        '& .MuiOutlinedInput-notchedOutline': {
                          borderColor: 'primary.main',
                          borderWidth: '2px',
                        },
                      },
                      '&.Mui-error': {
                        '& .MuiOutlinedInput-notchedOutline': {
                          borderColor: 'error.main',
                        },
                        '&:hover .MuiOutlinedInput-notchedOutline': {
                          borderColor: 'error.dark',
                        },
                      },
                    },
                    '& .MuiSelect-icon': {
                      color: 'primary.main',
                      right: '12px',
                    },
                  }}
                >
                  <InputLabel 
                    id="time-label"
                    sx={{
                      color: 'text.secondary',
                      '&.Mui-focused': {
                        color: 'primary.main',
                      },
                      '&.Mui-error': {
                        color: 'error.main',
                      },
                    }}
                  >
                    Preferred Time
                  </InputLabel>
                  <Select
                    labelId="time-label"
                    id="time"
                    name="time"
                    value={formData.time || ''}
                    onChange={handleTimeChange}
                    onBlur={() => setTouched(prev => ({ ...prev, time: true }))}
                    label="Preferred Time"
                    startAdornment={
                      <InputAdornment 
                        position="start" 
                        sx={{ 
                          ml: 1, 
                          color: formData.time ? 'primary.main' : 'action.active',
                          transition: 'color 0.2s cubic-bezier(0.4, 0, 0.2, 1)'
                        }}
                      >
                        <AccessTimeIcon fontSize="small" />
                      </InputAdornment>
                    }
                    MenuProps={{
                      PaperProps: {
                        sx: {
                          maxHeight: 300,
                          width: 260,
                          mt: 1,
                          boxShadow: 3,
                          borderRadius: 2,
                          overflow: 'hidden',
                          '&::-webkit-scrollbar': {
                            width: '8px',
                          },
                          '&::-webkit-scrollbar-track': {
                            background: 'transparent',
                          },
                          '&::-webkit-scrollbar-thumb': {
                            backgroundColor: 'rgba(0, 0, 0, 0.2)',
                            borderRadius: '4px',
                            '&:hover': {
                              backgroundColor: 'rgba(0, 0, 0, 0.3)',
                            },
                          },
                        },
                      },
                      MenuListProps: {
                        sx: {
                          py: 0.5,
                          '& .MuiMenuItem-root': {
                            minHeight: 48,
                            fontSize: '0.9375rem',
                            transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                            '&.Mui-selected': {
                              backgroundColor: 'primary.light',
                              color: 'primary.contrastText',
                              '&:hover': {
                                backgroundColor: 'primary.main',
                              },
                              '& .MuiSvgIcon-root': {
                                color: 'primary.contrastText',
                              },
                            },
                            '&:active': {
                              backgroundColor: 'action.selected',
                            },
                            '&:not(:last-child)': {
                              marginBottom: '2px',
                            },
                          },
                        },
                      },
                      transitionDuration: 150,
                      transitionTimingFunction: 'cubic-bezier(0.4, 0, 0.2, 1)',
                    }}
                    sx={{
                      '& .MuiSelect-select': {
                        display: 'flex',
                        alignItems: 'center',
                        padding: '14.5px 14px',
                        '&:focus': {
                          backgroundColor: 'transparent',
                        },
                      },
                    }}
                    renderValue={(selected) => {
                      const time = TIME_SLOTS.find(t => t.value === selected);
                      return (
                        <Box sx={{ 
                          display: 'flex', 
                          alignItems: 'center',
                          color: formData.time ? 'text.primary' : 'text.secondary',
                        }}>
                          <AccessTimeIcon 
                            sx={{ 
                              color: formData.time ? 'primary.main' : 'action.active',
                              mr: 1.5, 
                              fontSize: '1.25rem',
                              flexShrink: 0,
                            }} 
                          />
                          <Typography 
                            variant="body1"
                            sx={{ 
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              whiteSpace: 'nowrap',
                              fontWeight: formData.time ? 500 : 400,
                            }}
                          >
                            {time ? time.label : 'Select a time'}
                          </Typography>
                        </Box>
                      );
                    }}
                  >
                    {Object.entries(TIME_SLOTS_GROUPED).map(([period, times]) => [
                      <ListSubheader 
                        key={`header-${period}`}
                        sx={{
                          backgroundColor: 'background.paper',
                          background: 'linear-gradient(195deg, rgb(244, 247, 252), rgb(238, 242, 249))',
                          color: 'text.secondary',
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          lineHeight: '36px',
                          textTransform: 'uppercase',
                          letterSpacing: '0.5px',
                          borderBottom: '1px solid',
                          borderColor: 'divider',
                          position: 'sticky',
                          top: 0,
                          zIndex: 1,
                          backdropFilter: 'blur(8px)',
                          WebkitBackdropFilter: 'blur(8px)',
                          display: 'flex',
                          alignItems: 'center',
                          px: 2,
                        }}
                      >
                        <AccessTimeIcon sx={{ fontSize: '1rem', mr: 1, opacity: 0.8 }} />
                        <span>{period} Hours</span>
                      </ListSubheader>,
                      ...times.map((time) => (
                        <MenuItem 
                          key={time.value} 
                          value={time.value}
                          disabled={time.disabled}
                          selected={formData.time === time.value}
                          sx={{
                            pl: 4,
                            pr: 2,
                            py: 1.25,
                            mx: 1,
                            borderRadius: 1,
                            '&.Mui-disabled': {
                              opacity: 0.5,
                              fontStyle: 'italic',
                              pointerEvents: 'none',
                            },
                            '&:hover': {
                              backgroundColor: 'action.hover',
                            },
                            '&.Mui-selected': {
                              backgroundColor: 'primary.main',
                              color: 'primary.contrastText',
                              '&:hover': {
                                backgroundColor: 'primary.dark',
                              },
                              '& .MuiTypography-root': {
                                color: 'primary.contrastText',
                                fontWeight: 500,
                              },
                            },
                            '&:active': {
                              transform: 'scale(0.98)',
                            },
                          }}
                        >
                          <Box sx={{ 
                            display: 'flex', 
                            alignItems: 'center',
                            width: '100%',
                            justifyContent: 'space-between',
                            pr: 1,
                          }}>
                            <Typography 
                              variant="body1"
                              sx={{
                                fontWeight: formData.time === time.value ? 600 : 400,
                                color: formData.time === time.value ? 'inherit' : 'text.primary',
                                transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                              }}
                            >
                              {time.label}
                            </Typography>
                            {formData.time === time.value && (
                              <CheckIcon 
                                sx={{
                                  color: 'primary.contrastText',
                                  fontSize: '1.1rem',
                                  opacity: 1,
                                  transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
                                }}
                              />
                            )}
                          </Box>
                        </MenuItem>
                      )),
                      <Divider 
                        key={`divider-${period}`} 
                        sx={{ 
                          my: 0.5,
                          opacity: 0.1,
                          backgroundColor: 'divider',
                          height: '1px',
                        }} 
                      />
                    ])}
                  </Select>
                  {touched.time && !formData.time && (
                    <FormHelperText 
                      error 
                      sx={{ 
                        ml: 1.5,
                        mt: 0.75,
                        display: 'flex',
                        alignItems: 'center',
                        color: 'error.main',
                        backgroundColor: 'error.light',
                        borderRadius: 1,
                        px: 1.5,
                        py: 0.75,
                        width: 'fit-content',
                        '& .MuiSvgIcon-root': {
                          mr: 1,
                          fontSize: '1.1rem',
                        },
                      }}
                    >
                      <ErrorOutlineIcon fontSize="inherit" />
                      Please select a preferred time for your appointment
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

            {/* Additional Notes */}
            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={4}
                label="Additional Notes"
                name="notes"
                value={formData.notes}
                onChange={handleChange}
                placeholder="Any special requirements or questions..."
                InputProps={{
                  startAdornment: <NotesIcon sx={{ color: 'action.active', mr: 1, mt: 1, alignSelf: 'flex-start' }} />
                }}
              />
            </Grid>

            {/* Submit Button */}
            <Grid item xs={12} sx={{ mt: 2 }}>
              <Box display="flex" justifyContent="space-between" alignItems="center">
                <Button
                  type="button"
                  variant="outlined"
                  onClick={() => onClose && onClose()}
                  disabled={loading}
                  sx={{ minWidth: 120 }}
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  variant="contained"
                  color="primary"
                  disabled={loading}
                  startIcon={loading ? <CircularProgress size={20} color="inherit" /> : null}
                >
                  {loading ? 'Booking...' : 'Book Appointment'}
                </Button>
              </Box>
            </Grid>
          </Grid>
        </form>
      )}
    </Paper>
  </Container>
  );
}

export default BookAppointmentForm;
